// ============================================================================
// DisplayPort2_apb: APB4 register wrapper around DisplayPort2_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/DisplayPort2.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/DisplayPort2.md
// ============================================================================
module DisplayPort2_apb (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic lane_p,
  output logic lane_valid,
  output logic link_trained,
  output logic train_fail,
  output logic aux_tx_p,
  output logic aux_tx_en,
  input logic aux_rx_p,
  input logic sink_present,
  output logic edid_valid
);
  localparam logic [31:0] ID_VALUE = 32'h44320200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [7:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd8) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_lane_valid;
  logic          c_link_trained;
  logic          c_train_fail;
  logic [63:0]   c_edid;
  logic          c_edid_valid;
  logic          c_irq;
  DisplayPort2_top u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .lane_p(lane_p),
    .lane_valid(c_lane_valid),
    .link_trained(c_link_trained),
    .train_fail(c_train_fail),
    .aux_tx_p(aux_tx_p),
    .aux_tx_en(aux_tx_en),
    .aux_rx_p(aux_rx_p),
    .sink_present(sink_present),
    .edid(c_edid),
    .edid_valid(c_edid_valid),
    .irq(c_irq)
  );
  assign lane_valid = c_lane_valid;  // also readable in the registers
  assign link_trained = c_link_trained;  // also readable in the registers
  assign train_fail = c_train_fail;  // also readable in the registers
  assign edid_valid = c_edid_valid;  // also readable in the registers

  // ---------------- registers ----------------
  logic [1:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[1:0] & wmask[1:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[1:0]) | (PWDATA[1:0] & wmask[1:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
    end
  end

  // ---------------- core inputs ----------------

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_link_trained;
    irq_set[1] = c_irq;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'({c_edid_valid, c_train_fail, c_link_trained, c_lane_valid});
      10'd6: apb_rdata = 32'({c_edid[31:0]});
      10'd7: apb_rdata = 32'({c_edid[63:32]});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
